import {requirePublicPlatform} from './public-platform.mjs';
import {pickupConventions} from './colours.mjs';
import {readGeneratorURL,generatorURL,installationGuideURL,updateKitFromDiagram,builderURL,builderDiagramURL} from './session.mjs';
import {circuitForKit} from '../les-paul-kits/diagram.mjs';
import {explainStages} from './explain.mjs';
import {defaults,makeCircuit,endpoint,net,inspectComponent,colourCodes,kitLink,layoutInfo} from './model.mjs';
import {drawCircuit} from './render.mjs';
const $=s=>document.querySelector(s),form=$('#generator-form');let kitContext=null,circuit,selection=null,filter='all',zoom=1,step=0;
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
function paint(){const active=document.activeElement,focusAttribute=['data-component','data-wire','data-terminal'].find(a=>active?.hasAttribute?.(a)),focusValue=focusAttribute?active.getAttribute(focusAttribute):null;const mount=$('#generator-mount'),viewport=$('#generator-viewport'),left=viewport.scrollLeft,top=viewport.scrollTop;mount.innerHTML=drawCircuit(circuit,{selection,filter});mount.style.width=zoom*100+'%';viewport.scrollLeft=left;viewport.scrollTop=top;if(focusAttribute)mount.querySelector(`[${focusAttribute}="${focusValue}"]`)?.focus({preventScroll:true});$('#zoom-level').textContent=Math.round(zoom*100)+'%';$('#zoom-out').disabled=zoom<=1;$('#zoom-in').disabled=zoom>=2.5;}
function stagesForCircuit(){return explainStages(circuit);}
function explain(){const stages=stagesForCircuit(),stage=stages[step];selection={kind:'stage',ids:stage.ids};$('#explain-step').textContent=`${step+1} / ${stages.length} · ${stage.label}`;$('#explain-description').textContent=stage.description;$('#explain-back').disabled=step===0;$('#explain-next').disabled=step===stages.length-1;paint();}
function clear(){selection=null;$('#inspection-title').textContent='Your workbench';$('#inspection-description').textContent='Select a component to inspect its terminals, or a wire to trace connected wiring.';$('#inspection-content').replaceChildren();paint();}
function inspect(kind,id){
 if(kind==='terminal'){id=id.split('.')[0];kind='component';}
 selection={kind,id};$('#explain-panel').open=false;const root=$('#inspection-content');root.replaceChildren();
 if(kind==='component'){
  const info=inspectComponent(circuit,id);$('#inspection-title').textContent=info.label;$('#inspection-description').textContent=info.value;
  const dl=el('dl');for(const terminal of info.terminals){const row=el('div');row.append(el('dt',terminal.label),el('dd',terminal.connections.length?terminal.connections.join(' · '):'No external wire · leave unconnected'));dl.append(row);}root.append(dl);
  if(['toggle','blade','superswitch'].includes(circuit.components.find(c=>c.id===id).type)){const p=el('p','Closed contacts: '+circuit.contacts.map(pair=>pair.map(ref=>endpoint(circuit,ref).terminal.label).join(' ↔ ')).join('; '));root.append(p);}
 }else{
  const wire=circuit.connections.find(w=>w.id===id),refs=net(circuit,wire.from);$('#inspection-title').textContent='Connection trace';$('#inspection-description').textContent='Connected wiring and closed selector contacts. No traversal through pot resistance, capacitor or resistor internals.';
  const ul=el('ul');for(const ref of refs){const e=endpoint(circuit,ref);ul.append(el('li',e.component.label+' / '+e.terminal.label));}root.append(ul);
 }
 paint();
}
function render(){
 try{const state=Object.fromEntries(Object.keys(defaults).map(k=>[k,form.elements.namedItem(k).value]));requirePublicPlatform(state);let notice='';
 if(state.wiring==='50s'&&state.bleed!=='none'){state.bleed='none';form.elements.namedItem('bleed').value='none';notice='Treble bleed removed because 50s wiring is selected.';}
 form.elements.namedItem('bleed').disabled=state.wiring==='50s';$('#bleed-reason').hidden=state.wiring!=='50s';if(kitContext&&state.guitar==='les-paul'){kitContext=updateKitFromDiagram(kitContext,state);circuit=circuitForKit(kitContext,{colours:state.colours,position:state.position,shielding:state.shielding});}else{kitContext=null;circuit=makeCircuit(state);}selection=null;clear();
 history.replaceState(null,'',generatorURL(state,kitContext));$('#installation-guide').href=installationGuideURL(state,kitContext);$('#installation-guide').hidden=state.guitar!=='les-paul';
 const plainLink=kitLink(circuit),link=kitContext?builderDiagramURL(kitContext,state):plainLink?plainLink+'&g='+encodeURIComponent(JSON.stringify(state)):null;$('#build-kit').hidden=!link;if(link)$('#build-kit').href=link;$('#kit-transfer-note').textContent=kitContext?'Your complete kit specification is retained. This is the full installation circuit. Return to the Builder and select Your Kit to highlight the parts Apparition supplies.':link?'The circuit transfers with an Epiphone jack and Epiphone-style toggle selected. Review brands, shaft length, fitment and price in the builder.':'A matching kit product and fitment specification are not available for this layout yet. You can still inspect, export and print its wiring.';
 $('#generator-status').textContent=notice||(!colourCodes[state.colours].verified?'Colour code not yet verified. Generic conductors are shown; verify your exact pickup convention.':'Circuit generated. Select any component or connection to inspect it.');$('#export-svg').disabled=false;$('#print-diagram').disabled=false;
 const legend=$('#colour-legend');legend.replaceChildren();const table=el('dl');for(const [key,[colour,label]] of Object.entries(colourCodes[state.colours].wires)){const row=el('div');row.append(el('dt',key),el('dd',label));table.append(row);}if(['strat','tele'].includes(state.guitar))legend.append(el('p','Single-coil leads are identified by electrical function: hot and ground. Check the pickup maker’s lead identification; no manufacturer colour mapping is assumed.'));else legend.append(el('p',colourCodes[state.colours].label),table);
 if($('#explain-panel').open)explain();
 }catch(error){$('#generator-status').textContent="This configuration isn't available yet. "+error.message;$('#generator-mount').replaceChildren();$('#export-svg').disabled=true;$('#print-diagram').disabled=true;$('#build-kit').hidden=true;}
}
form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('change',e=>{if(e.target.name==='guitar'){kitContext=null;setLayout(true);}render();});form.addEventListener('reset',()=>setTimeout(()=>{kitContext=null;setLayout(true);render();},0));
$('#generator-mount').addEventListener('click',e=>{const target=e.target.closest('[data-terminal],[data-component],[data-wire]');if(target)inspect(target.dataset.terminal?'terminal':target.dataset.component?'component':'wire',target.dataset.terminal||target.dataset.component||target.dataset.wire);});
$('#generator-mount').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){const t=e.target.closest('[data-terminal],[data-component],[data-wire]');if(t){e.preventDefault();inspect(t.dataset.terminal?'terminal':t.dataset.component?'component':'wire',t.dataset.terminal||t.dataset.component||t.dataset.wire);}}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;selection=null;$('#explain-panel').open=false;document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));clear();}));
$('#clear-selection').addEventListener('click',()=>{$('#explain-panel').open=false;clear();});
for(const [id,delta] of [['zoom-in',.25],['zoom-out',-.25]])$('#'+id).addEventListener('click',()=>{zoom=Math.max(1,Math.min(2.5,zoom+delta));paint();});$('#zoom-fit').addEventListener('click',()=>{zoom=1;paint();});
$('#explain-panel').addEventListener('toggle',()=>{if($('#explain-panel').open)explain();else if(selection?.kind==='stage')clear();});$('#explain-back').addEventListener('click',()=>{step=Math.max(0,step-1);explain();});$('#explain-next').addEventListener('click',()=>{step=Math.min(stagesForCircuit().length-1,step+1);explain();});
$('#export-svg').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([drawCircuit(circuit,{exporting:true})],{type:'image/svg+xml'})),a=el('a');a.href=url;a.download=`Apparition-${circuit.state.guitar}-${circuit.state.wiring}-wiring.svg`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
let beforePrint;
window.addEventListener('beforeprint',()=>{if(!circuit)return;beforePrint={selection,filter,zoom};$('#generator-mount').innerHTML=drawCircuit(circuit,{exporting:true});$('#generator-mount').style.width='100%';});window.addEventListener('afterprint',()=>{if(beforePrint){({selection,filter,zoom}=beforePrint);beforePrint=null;paint();}});$('#print-diagram').addEventListener('click',()=>window.print());
function setLayout(reset){const guitar=form.elements.guitar.value,lp=['les-paul','sg'].includes(guitar),positions=form.elements.position,old=positions.value;positions.replaceChildren();for(const [v,label] of Object.entries(layoutInfo[guitar].positions)){const option=el('option',label);option.value=v;positions.append(option);}positions.value=!reset&&layoutInfo[guitar].positions[old]?old:lp?'both':'1';form.elements.wiring.disabled=!lp;form.elements.wiring.closest('label').hidden=!lp;if(!lp)form.elements.wiring.value='modern';$('#bridge-cap-control').hidden=!lp;form.elements.colours.disabled=['strat','tele'].includes(guitar);if(form.elements.colours.disabled)form.elements.colours.value='generic';if(reset){form.elements.neckCap.value=guitar==='prs'?'0.033':lp?'0.022':'0.047';form.elements.bridgeCap.value=form.elements.neckCap.value;form.elements.bleed.value=guitar==='prs'?'prs':'none';}$('#layout-description').textContent=layoutInfo[guitar].description;}
const colourSelect=form.elements.colours;colourSelect.replaceChildren();for(const [id,entry] of Object.entries(pickupConventions)){const option=el('option',entry.label+(entry.verified?'':' · unverified'));option.value=id;colourSelect.append(option);}
let initialError='';try{const saved=readGeneratorURL(location.search);requirePublicPlatform(saved.state);kitContext=saved.kit;for(const [key,value] of Object.entries(saved.state))form.elements.namedItem(key).value=value;if(kitContext&&['premium','overkill'].includes(kitContext.bleed)){const option=el('option',kitContext.bleed==='premium'?'Premium Sprague Duncan-style · supplied kit':'Apparition Overkill-Pasitor · supplied kit');option.value=kitContext.bleed;form.elements.bleed.append(option);form.elements.bleed.value=kitContext.bleed;}}catch(e){initialError=e.message;}
setLayout(false);
if(matchMedia('(max-width:800px)').matches)$('#generator-options').open=false;render();if(initialError)$('#generator-status').textContent=initialError+' The default circuit is shown.';
